import React, { useState } from "react";
import { motion } from "framer-motion";
import { UploadCloud } from "lucide-react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const Interview = () => {
  const [video, setVideo] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [message, setMessage] = useState("");
  const navigate = useNavigate();

  const handleFileChange = (e) => {
    setVideo(e.target.files[0]);
  };

  const handleUpload = async () => {
    if (!video) {
      setMessage("Please select a video first!");
      return;
    }

    const formData = new FormData();
    formData.append("file", video);

    try {
      setUploading(true);
      setMessage("");

      // Backend upload call
      const res = await axios.post("http://localhost:8080/api/video/upload", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });

      navigate("/feedback", { state: { feedback: res.data.feedback } });
    } catch (err) {
      console.error(err);
      setMessage("❌ Upload failed! Try again.");
    } finally {
      setUploading(false);
    }
  };

  return (
    <div className="min-h-[80vh] flex flex-col items-center justify-center text-center p-8">
      <motion.h1
        initial={{ opacity: 0, y: -20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
        className="text-4xl font-bold mb-6"
      >
        Upload Your Interview Video
      </motion.h1>

      <motion.div
        initial={{ opacity: 0, scale: 0.95 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 0.5 }}
        className="bg-white/10 backdrop-blur-md rounded-xl p-8 shadow-lg w-full max-w-md"
      >
        <label
          htmlFor="video-upload"
          className="cursor-pointer flex flex-col items-center justify-center border-2 border-dashed border-blue-400 p-6 rounded-xl hover:bg-blue-800/30 transition-all"
        >
          <UploadCloud className="w-12 h-12 text-blue-300 mb-2" />
          <span className="text-blue-100">
            {video ? video.name : "Click to choose your video"}
          </span>
          <input
            id="video-upload"
            type="file"
            accept="video/*"
            onChange={handleFileChange}
            className="hidden"
          />
        </label>

        <button
          onClick={handleUpload}
          disabled={uploading}
          className={`mt-6 w-full py-3 rounded-lg font-semibold text-white transition-all ${
            uploading
              ? "bg-blue-500 cursor-not-allowed"
              : "bg-blue-600 hover:bg-blue-700"
          }`}
        >
          {uploading ? "Uploading..." : "Upload & Analyze"}
        </button>

        {message && (
          <p className="text-sm text-yellow-300 mt-3">{message}</p>
        )}
      </motion.div>
    </div>
  );
};

export default Interview;
